package com.tvos.neo;import android.content.*;import java.util.*;public class NeoAppLockTest{
 static class Memory implements SharedPreferences,SharedPreferences.Editor{Map<String,Object> d=new HashMap<>();public Map<String,?> getAll(){return new HashMap<>(d);}public String getString(String k,String v){return (String)d.getOrDefault(k,v);}public int getInt(String k,int v){return (Integer)d.getOrDefault(k,v);}public long getLong(String k,long v){return (Long)d.getOrDefault(k,v);}public boolean getBoolean(String k,boolean v){return (Boolean)d.getOrDefault(k,v);}public boolean contains(String k){return d.containsKey(k);}public Editor edit(){return this;}public Editor putString(String k,String v){d.put(k,v);return this;}public Editor putInt(String k,int v){d.put(k,v);return this;}public Editor putLong(String k,long v){d.put(k,v);return this;}public Editor putBoolean(String k,boolean v){d.put(k,v);return this;}public Editor remove(String k){d.remove(k);return this;}public void apply(){}}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[]a){Memory memory=new Memory();Context c=new Context(){public SharedPreferences getSharedPreferences(String n,int m){return memory;}};NeoAppLock lock=new NeoAppLock(c);String app="org.example.video";
 check(!lock.blocked(app),"Unconfigured");lock.setPin("0123");check(lock.verify("0123"),"PIN with leading zero");check(!memory.d.containsValue("0123"),"No plaintext PIN");check(!lock.verify("1234"),"Incorrect PIN");check(!lock.verify("123"),"PIN length");lock.configure(app,true,15);check(lock.blocked(app),"Initially locked");lock.grant(app);check(!lock.blocked(app),"Grant");android.os.SystemClock.now+=899999;check(!lock.blocked(app),"Before expiry");android.os.SystemClock.now++;check(lock.blocked(app),"Exact expiry");lock.grant(app);android.provider.Settings.Global.boot++;check(lock.blocked(app),"Reboot invalidation");lock.grant(app);lock.revoke();check(lock.blocked(app),"Revoke");
 for(int m=15;m<=240;m+=15){lock.configure(app,true,m);check(lock.minutes(app)==m,"Interval");}try{lock.configure(app,true,16);throw new AssertionError("Invalid interval allowed");}catch(IllegalArgumentException good){}
 for(String pkg:Arrays.asList("android","com.android.tv.settings","com.android.systemui","com.tvos.neo")){lock.configure(pkg,true,15);check(!lock.enabled(pkg),"Core exclusion");}
 lock.configure(app,false,15);check(!lock.blocked(app),"Disable");lock.setPin("5678");for(int i=0;i<5;i++)check(!lock.verify("0000"),"Failed attempts");check(!lock.verify("5678"),"Retry lockout");memory.remove("retry");check(lock.verify("5678"),"PIN recovery after cooldown");check(!lock.verify("0123"),"Old PIN invalid");System.out.println("PASS: PIN hashing, attempts, intervals, expiry, reboot, revoke and core exclusions");}}
